"use client";
import {
  GalleryInternalImage,
  GalleryInternalStyles,
  galleryStyle,
  useGalleryEnvironment,
  useGalleryIndex,
  type GalleryInternalProps,
  type GalleryInternalItem,
} from "./gallery-shared";
export interface ExpandingStripItem extends GalleryInternalItem {}
export interface ExpandingStripProps extends GalleryInternalProps {
  items: readonly ExpandingStripItem[];
  expandedRatio?: number;
  duration?: number;
  gap?: number;
}
export function ExpandingStrip(props: ExpandingStripProps) {
  const {
    items,
    expandedRatio = 4,
    duration = 0.8,
    gap = 0,
    height = 640,
    label = "Expanding image strip",
    className = "",
    style,
    renderCaption,
    onSelect,
  } = props;
  const env = useGalleryEnvironment();
  const { current, choose } = useGalleryIndex(props);
  return (
    <div
      ref={env.ref}
      className={`z-ag ${className}`}
      data-gallery="expanding-strip"
      data-index={current}
      role="region"
      aria-label={label}
      style={galleryStyle(height, { display: "flex", gap, ...style })}
    >
      <GalleryInternalStyles />
      {items.map((item, i) => (
        <button
          key={item.id}
          type="button"
          data-gallery-card={i}
          aria-pressed={current === i}
          aria-label={item.title ?? `Image ${i + 1}`}
          onPointerEnter={(e) => {
            if (e.pointerType !== "touch") choose(i);
          }}
          onFocus={() => choose(i)}
          onClick={() => {
            choose(i);
            onSelect?.(item, i);
          }}
          onKeyDown={(e) => {
            if (["ArrowRight", "ArrowLeft"].includes(e.key)) {
              e.preventDefault();
              const next = (i + (e.key === "ArrowRight" ? 1 : items.length - 1)) % items.length;
              choose(next);
              env.ref.current
                ?.querySelector<HTMLButtonElement>(`[data-gallery-card="${next}"]`)
                ?.focus();
            }
          }}
          style={{
            position: "relative",
            flex: current === i ? expandedRatio : 1,
            minWidth: 0,
            height: "100%",
            border: 0,
            padding: 0,
            overflow: "hidden",
            cursor: "pointer",
            transition: `flex ${env.reduced ? 0 : duration}s cubic-bezier(.22,1,.36,1)`,
          }}
        >
          <GalleryInternalImage
            item={item}
            style={{
              filter: current === i ? "brightness(.9)" : "brightness(.65)",
              transition: `filter ${duration}s`,
            }}
          />
          <div
            style={{
              position: "absolute",
              inset: 0,
              background: "linear-gradient(transparent 55%,#0007)",
            }}
          />
          <span
            style={{
              position: "absolute",
              bottom: 32,
              left: current === i ? 24 : "50%",
              color: "#fff",
              textAlign: "left",
              whiteSpace: "nowrap",
              writingMode: current === i ? "horizontal-tb" : "vertical-rl",
              transform: current === i ? "none" : "translateX(-50%) rotate(180deg)",
              fontSize: current === i ? "clamp(22px,4vw,42px)" : 18,
            }}
          >
            {renderCaption?.(item, i) ?? item.title}
            {current === i && item.description && (
              <small style={{ display: "block", fontSize: 13, marginTop: 8 }}>
                {item.description}
              </small>
            )}
          </span>
        </button>
      ))}
    </div>
  );
}
